create extension if not exists btree_gist;
create extension if not exists postgres_fdw;
create schema sink;
create collation sink.ci (provider = icu, locale = 'und-u-ks-level2', deterministic = false);
create type sink.mood as enum ('sad', 'ok', 'happy');
create type sink.pair as (a int, b text);
create type sink.floatrange as range (subtype = float8, subtype_diff = float8mi);
create domain sink.score as int not null default 0 constraint score_min check (value >= 0) constraint score_max check (value <= 100);
create sequence sink.ticket_seq as bigint increment by 5 minvalue 10 maxvalue 99999 start 100 cache 20 cycle;
create text search dictionary sink.simple_dict (template = pg_catalog.simple, stopwords = english);
create text search configuration sink.cfg (copy = pg_catalog.english);
alter text search configuration sink.cfg alter mapping for asciiword with sink.simple_dict, english_stem;

create table sink.accounts (
  id bigint generated by default as identity (start with 1000 increment by 10) primary key,
  email text collate sink.ci not null unique,
  mood sink.mood default 'ok',
  score sink.score,
  big text compression pglz,
  doubled int generated always as (id::int * 2) stored,
  created_at timestamptz not null default now()
) with (fillfactor = 80, autovacuum_enabled = false);
alter table sink.accounts alter column mood set statistics 250;
alter table sink.accounts alter column big set storage external;
alter table sink.accounts alter column score set (n_distinct = -0.5);
comment on table sink.accounts is 'people';
comment on column sink.accounts.email is 'login';
alter sequence sink.ticket_seq owned by sink.accounts.id;

create table sink.bookings (
  id int primary key,
  account_id bigint,
  room int not null,
  during tstzrange not null,
  note text,
  constraint bookings_no_overlap exclude using gist (room with =, during with &&),
  constraint bookings_note_len check (length(note) < 500) not valid
);
alter table sink.bookings add constraint bookings_account_fk foreign key (account_id) references sink.accounts (id) on delete set null deferrable initially deferred;
create index bookings_room_idx on sink.bookings (room) include (note) where note is not null;
create statistics sink.bookings_stats (ndistinct, dependencies) on room, account_id from sink.bookings;

create unlogged table sink.cache (k text primary key, v jsonb);
create table sink.base (id int, created_at timestamptz default now());
create table sink.child (extra text) inherits (sink.base);

create table sink.events (id int, region text not null, payload jsonb) partition by list (region);
create table sink.events_eu partition of sink.events for values in ('eu');
create table sink.events_default partition of sink.events default;
create server sink_remote foreign data wrapper postgres_fdw options (dbname 'elsewhere', port '5432');
create foreign table sink.events_us partition of sink.events for values in ('us') server sink_remote options (table_name 'events_us');
create foreign table sink.remote_items (id int not null, label text options (column_name 'name')) server sink_remote options (schema_name 'public', table_name 'items');
comment on foreign table sink.remote_items is 'remote';

create function sink.touch() returns trigger language plpgsql as $$ begin new.created_at = now(); return new; end $$;
create function sink.plus(x int) returns int language sql immutable parallel safe begin atomic select x + 1; end;
create function sink.account_count() returns bigint language sql stable begin atomic select count(*) from sink.accounts; end;
create function sink.twice(x int) returns int language sql immutable return sink.plus(x) + sink.plus(x);
create procedure sink.purge() language sql begin atomic delete from sink.cache where v is null; end;
create function sink.add2(a int, b int) returns int language sql immutable strict as 'select a + b';
create aggregate sink.total(int) (sfunc = sink.add2, stype = int, initcond = '0');

create trigger accounts_touch before update on sink.accounts for each row when (old.email is distinct from new.email) execute function sink.touch();
create constraint trigger bookings_check after insert on sink.bookings deferrable initially deferred for each row execute function sink.touch();
create rule cache_no_delete as on delete to sink.cache do instead nothing;

alter table sink.accounts enable row level security;
create policy accounts_self on sink.accounts for select to public using (email = current_user);
create policy accounts_ins on sink.accounts as restrictive for insert to public with check (score >= 0);

create view sink.happy_accounts with (security_barrier = true) as select id, email from sink.accounts where mood = 'happy';
create materialized view sink.mood_counts with (fillfactor = 70) as select mood, count(*) as n from sink.accounts group by mood with no data;
create unique index mood_counts_mood on sink.mood_counts (mood);

grant select on sink.happy_accounts to public;
grant select (id, email), update (email) on sink.accounts to public;
grant usage on sequence sink.ticket_seq to public;
grant execute on function sink.plus(int) to public;

create publication sink_pub for table sink.accounts (id, email) where (id > 0), sink.bookings with (publish = 'insert, update');
